module longmod1000_leaf_ (i, o);
  input i;
  output o;
  INV_X1 g (.A(i), .ZN(o));
endmodule
module longmod1000_mid_ (i, o);
  input i;
  output o;
  wire w;
  longmod1000_leaf_ u (.i(i), .o(w));
  BUF_X1 b (.A(w), .Z(o));
endmodule
module top (a, y);
  input a;
  output y;
  wire w;
  longmod1000_mid_ u (.i(a), .o(w));
  INV_X1 v (.A(w), .ZN(y));
endmodule
